      '/auth/send-otp': { post: { tags: ['Auth'], summary: 'Email a one-time sign-in code', description: 'Send `phone` or `email`; the code goes to the email address on the matching account (never to an address in the request). The answer is the same whether or not an account matches. Staff accounts cannot sign in by code. One code per 30 s, 5 per 15 min; codes last 5 minutes. `verify_phone` is not available while WhatsApp is paused (503). Needs email (SMTP) on the server, else 503 OTP_NOT_CONFIGURED; development servers return `devCode`.', requestBody: body({ type: 'object', properties: { phone: { type: 'string' }, email: { type: 'string' }, purpose: { type: 'string', enum: ['login'] } } }, { phone: '+919999999999', purpose: 'login' }), responses: { 200: ok('Sent', { type: 'object', properties: { message: { type: 'string' }, expiresInSeconds: { type: 'integer' } } }), 400: E[400], 429: E[429], 503: err('OTP not configured') } } },
      '/auth/verify-otp': { post: { tags: ['Auth'], summary: 'Verify a one-time code', description: 'Send the same `phone` or `email` as for /auth/send-otp. Returns a session like /auth/login (404 ACCOUNT_NOT_FOUND if no account matches; 403 STAFF_PASSWORD_REQUIRED for staff). Wrong code → OTP_INVALID (5 tries); expired → OTP_EXPIRED.', requestBody: body({ type: 'object', required: ['otp'], properties: { phone: { type: 'string' }, email: { type: 'string' }, otp: { type: 'string', example: '123456' }, purpose: { type: 'string', enum: ['login'] } } }, { phone: '+919999999999', otp: '123456', purpose: 'login' }), responses: { 200: ok('Signed in / verified', ref('AuthResult')), 400: E[400], 404: E[404] } } },
